def f(n):
    if n == 0:
        return 0
    return n + f(n - 1)

print(f(4))

def g(L):
    if len(L) == 0:
        return 0
    if L[0] > 0:
        return 1 + g(L[1:])
    return g(L[1:])

print(g([3, -1, 0, 7, -5, 2]))

def h(n):
    if n <= 1:
        return 1
    return h(n - 1) + h(n - 2)

print(h(5))

def t(n):
    if n == 0:
        return 0
    return 1 + t(n - 2)

def fact(n):
    if n == 0:
        return 1
    return n * fact(n - 1)

print(fact(5))

def ds(n):
    if n < 10:
        return n
    return n % 10 + ds(n // 10)

print(ds(4096))

def m(L):
    if len(L) == 1:
        return L[0]
    rest = m(L[1:])
    if L[0] > rest:
        return L[0]
    return rest

print(m([4, 11, 6, 9]))

def c(n):
    if n < 2:
        return n
    return c(n - 1) + c(n - 2)

def f(L):
    if len(L) < 2:
        return []
    return [L[1]] + f(L[2:])

print(f([5, 8, 1, 9, 4, 7, 2]))

def w(n):
    if n == 1:
        return 0
    if n % 2 == 0:
        return 1 + w(n // 2)
    return 1 + w(n + 3)
